const r = msg.summaryRequest;
if (!r) return null;

msg.collection = "stoppages";
msg.operation = "find";

// Shift-boundary logic splits open stoppages at boundaries,
// therefore each stoppage document belongs to exactly one shift.
msg.payload = [
    {
        device: r.device,
        date: r.shiftDate,
        shift: r.shift
    },
    {
        sort: {
            stopStart_ts: 1
        }
    }
];

return msg;

const rows = Array.isArray(msg.payload) ? [...msg.payload] : [];
const r = msg.summaryRequest;

if (!r) return null;

// ========================================================
// GET CONFIGURATION
// ========================================================

const cfgAll = global.get("counterConfig") || {};
const cfg = cfgAll[r.device] || {};

const allSettings = global.get("lineSettings") || {};

const ls =
    allSettings[r.line] ||
    allSettings[String(r.line).toLowerCase()] ||
    {};


const lineSpeed =
    Math.max(
        0,
        Number(
            ls.lineSpeed ??
            cfg.lineSpeed ??
            0
        )
    );


const tileSize =
    String(
        ls.tileSize ??
        cfg.tileSize ??
        ""
    ).trim();


const configuredPlannedDowntime =
    Math.max(
        0,
        Number(
            ls.plannedDowntime ??
            cfg.plannedDowntime ??
            0
        )
    );


// ========================================================
// SHIFT TIME RANGE
// ========================================================

const fromMs =
    new Date(r.fromTime).getTime();

const toMs =
    new Date(r.toTime).getTime();

const now =
    Date.now();


if (
    !Number.isFinite(fromMs) ||
    !Number.isFinite(toMs) ||
    toMs <= fromMs
) {
    node.error(
        "Invalid shift time range",
        msg
    );

    return null;
}


// ========================================================
// HELPERS
// ========================================================

function round(v, n = 2) {

    const p =
        10 ** n;

    return Math.round(
        (Number(v || 0) + Number.EPSILON) * p
    ) / p;
}


function tileAreaM2(size) {

    const d =
        String(size || "")
            .toLowerCase()
            .replace(/\s+/g, "")
            .split("x")
            .map(Number);

    if (
        d.length !== 2 ||
        !d.every(
            v =>
                Number.isFinite(v) &&
                v > 0
        )
    ) {
        return 0;
    }

    // Tile dimensions assumed to be centimetres.
    return (
        d[0] *
        d[1]
    ) / 10000;
}


// ========================================================
// SHIFT TIME
// ========================================================

const calculationEndMs =
    Math.min(
        Math.max(now, fromMs),
        toMs
    );


const fullShiftMinutes =
    Math.max(
        0,
        (toMs - fromMs) / 60000
    );


const elapsedMinutes =
    Math.max(
        0,
        (calculationEndMs - fromMs) / 60000
    );


// ========================================================
// CLASSIFY DOWNTIME
//
// FINAL RULE:
//
// Planned -> Standard
//     Actual recorded duration is planned,
//     but limited by configured standard allowance.
//
//     Any duration above the allowance becomes
//     UNPLANNED.
//
// Planned -> Additional
//     Entire recorded duration is planned.
//
// Everything else
//     Unplanned.
//
// IMPORTANT:
//
// Unused configured standard allowance is NOT
// automatically distributed across the shift.
// ========================================================

let totalDowntimeMinutes = 0;

let standardActualMinutes = 0;
let additionalPlannedMinutes = 0;
let explicitUnplannedMinutes = 0;

let completedStops = 0;
let openStop = false;

let currentOpenStopMinutes = 0;
let maximumDowntimeMinutes = 0;


for (const stop of rows) {

    let start =
        Number(stop.stopStart_ts);

    if (!Number.isFinite(start)) {
        continue;
    }


    // Clamp start to shift boundary.
    start =
        Math.max(
            start,
            fromMs
        );


    const isOpen =
        stop.stopStop_ts === null ||
        stop.stopStop_ts === undefined;


    let end;

    if (isOpen) {

        end =
            calculationEndMs;

    } else {

        end =
            Number(
                stop.stopStop_ts
            );

        if (!Number.isFinite(end)) {
            continue;
        }

        end =
            Math.min(
                end,
                calculationEndMs,
                toMs
            );
    }


    if (end <= start) {
        continue;
    }


    const durationMinutes =
        (end - start) / 60000;


    // ----------------------------------------
    // TOTAL ACTUAL DOWNTIME
    // ----------------------------------------

    totalDowntimeMinutes +=
        durationMinutes;


    maximumDowntimeMinutes =
        Math.max(
            maximumDowntimeMinutes,
            durationMinutes
        );


    // ----------------------------------------
    // CLASSIFICATION
    // ----------------------------------------

    const downtimeType =
        String(
            stop.downtimeType ||
            "unplanned"
        ).toLowerCase();


    const plannedCategory =
        String(
            stop.plannedCategory ||
            ""
        ).toLowerCase();


    if (
        downtimeType === "planned" &&
        plannedCategory === "standard"
    ) {

        standardActualMinutes +=
            durationMinutes;

    }

    else if (
        downtimeType === "planned" &&
        plannedCategory === "additional"
    ) {

        additionalPlannedMinutes +=
            durationMinutes;

    }

    else {

        explicitUnplannedMinutes +=
            durationMinutes;

    }


    // ----------------------------------------
    // STOP COUNTS
    // ----------------------------------------

    if (isOpen) {

        openStop = true;

        currentOpenStopMinutes =
            Math.max(
                currentOpenStopMinutes,
                durationMinutes
            );

    } else {

        completedStops += 1;

    }
}


// ========================================================
// STANDARD PLANNED DOWNTIME
// ========================================================

const allowance =
    configuredPlannedDowntime;


// IMPORTANT:
//
// If allowance = 0,
// manually classified Standard Planned downtime
// remains planned.
//
// This matches the live KPI rule.

const standardUsed =
    allowance > 0
        ? Math.min(
            standardActualMinutes,
            allowance
        )
        : standardActualMinutes;


const remainingStandardAllowance =
    allowance > 0
        ? Math.max(
            0,
            allowance -
            standardUsed
        )
        : 0;


const standardExcess =
    allowance > 0
        ? Math.max(
            0,
            standardActualMinutes -
            allowance
        )
        : 0;



const standardApplied =
    standardUsed;


// ========================================================
// PLANNED / UNPLANNED DOWNTIME
// ========================================================

const plannedDowntimeMinutes =
    standardApplied +
    additionalPlannedMinutes;


// Everything not accepted as planned is unplanned.
//
// This automatically includes:
//     explicit unplanned
//     standard excess

const unplannedDowntimeMinutes =
    Math.max(
        0,
        totalDowntimeMinutes -
        plannedDowntimeMinutes
    );


// // ========================================================
// // PRODUCTION TIME
// // ========================================================

// // Planned production time:
// //
// // Elapsed shift time minus accepted planned downtime.

// const plannedProductionMinutes =
//     Math.max(
//         0,
//         elapsedMinutes -
//         plannedDowntimeMinutes
//     );


// // IMPORTANT:
// //
// // Physical operating time depends ONLY on
// // actual stoppage duration.
// //
// // Planned/unplanned classification does not
// // change physical operating time.

// // ========================================================
// // RUN CONFIRMATION CORRECTION
// // ========================================================
// //
// // STOP_END is confirmed only after the line has been running
// // continuously for requiredRunTimeMs.
// //
// // Tiles are already counted during this confirmation period,
// // while that same period is still included in the recorded
// // downtime. Add it back once for every COMPLETED stop.
// //
// // Open stops are intentionally excluded because they have not
// // completed the recovery-confirmation period yet.

// const requiredRunTimeMs =
//     Math.max(
//         0,
//         Number(
//             ls.requiredRunTimeMs ??
//             cfg.requiredRunTimeMs ??
//             60000
//         )
//     );

// const runConfirmationMinutes =
//     requiredRunTimeMs / 60000;

// const recoveryCorrectionMinutes =
//     completedStops *
//     runConfirmationMinutes;



// const actualOperatingMinutes =
//     Math.max(
//         0,
//         Math.min(
//             elapsedMinutes,
//             elapsedMinutes -
//             totalDowntimeMinutes +
//             recoveryCorrectionMinutes
//         )
//     );


// // ========================================================
// // AVAILABILITY
// // ========================================================

// const availability =
//     plannedProductionMinutes > 0
//         ? (
//             actualOperatingMinutes /
//             (plannedProductionMinutes+recoveryCorrectionMinutes)
//         ) * 100
//         : 0;

// ========================================================
// PRODUCTION TIME
// ========================================================

const plannedProductionMinutes = Math.max(
    0,
    elapsedMinutes - plannedDowntimeMinutes
);

// Stored STOP_END is already backdated to runningSince.
// The confirmation minute is therefore already operating time.
const actualOperatingMinutes = Math.max(
    0,
    Math.min(
        elapsedMinutes,
        elapsedMinutes - totalDowntimeMinutes
    )
);

// ========================================================
// AVAILABILITY
// ========================================================

const availability =
    plannedProductionMinutes > 0
        ? (actualOperatingMinutes / plannedProductionMinutes) * 100
        : 0;


// ========================================================
// PRODUCTION
// ========================================================

const tileCount =
    Math.max(
        0,
        Number(
            r.tileCount || 0
        )
    );


const areaPerTile =
    tileAreaM2(
        tileSize
    );


const production =
    tileCount *
    areaPerTile;


// ========================================================
// TARGET PRODUCTION
//
// Target is based on PHYSICAL OPERATING TIME.
//
// Example:
//
// Operating time = 400 min
// Rated speed    = 12 tiles/min
//
// Target = 4,800 tiles
// ========================================================

const targetTiles =
    lineSpeed > 0
        ? lineSpeed *
          actualOperatingMinutes
        : 0;


const targetProduction =
    targetTiles *
    areaPerTile;


// ========================================================
// PERFORMANCE
// ========================================================

const performance =
    targetTiles > 0
        ? (
            tileCount /
            targetTiles
        ) * 100
        : 0;


// ========================================================
// QUALITY
// ========================================================

// No reject / quality counter is currently available.
// Therefore quality remains 100%.

const quality =
    100;


// ========================================================
// OLE
// ========================================================

const ole =
    (
        availability *
        performance *
        quality
    ) / 10000;


// ========================================================
// BUILD SHIFT SUMMARY
// ========================================================

msg.payload = {

    lineStats: {

        // ----------------------------------------
        // IDENTIFICATION
        // ----------------------------------------

        device:
            r.device,

        lineName:
            r.line,

        machine:
            r.machine || "",

        shift:
            r.shift,

        shiftDate:
            r.shiftDate,

        shiftStart:
            r.fromTime,

        shiftEnd:
            r.toTime,

        status:
            r.shiftStatus ||
            "Unknown",

        // Configuration at the end of this shift. Run IDs inside
        // codeWiseProduction / Timeline identify individual production.
        productionRunId: r.productionRunIdAtShiftEnd || null,
        productionRunStartTime: r.productionRunStartTimeAtShiftEnd || null,


        // ----------------------------------------
        // KPI
        // ----------------------------------------

        ole:
            round(ole),

        availability:
            round(availability),

        performance:
            round(performance),

        quality:
            quality,


        // ----------------------------------------
        // PRODUCTION
        // ----------------------------------------

        tileCount:
            Math.round(tileCount),

        production:
            round(production),

        productionUnit:
            "m²",

        targetTiles:
            round(targetTiles, 0),

        targetProduction:
            round(targetProduction),


        // ----------------------------------------
        // SHIFT TIME
        // ----------------------------------------

        fullShiftMinutes:
            round(fullShiftMinutes),

        elapsedShiftMinutes:
            round(elapsedMinutes),

        plannedProductionMinutes:
            round(
                plannedProductionMinutes
            ),

        actualOperatingMinutes:
            round(
                actualOperatingMinutes
            ),


        // ----------------------------------------
        // DOWNTIME
        // ----------------------------------------

        totalDowntimeMinutes:
            round(
                totalDowntimeMinutes
            ),

        plannedDowntimeMinutes:
            round(
                plannedDowntimeMinutes
            ),

        unplannedDowntimeMinutes:
            round(
                unplannedDowntimeMinutes
            ),


        // ----------------------------------------
        // STANDARD PLANNED
        // ----------------------------------------

        configuredPlannedDowntime:
            round(
                configuredPlannedDowntime
            ),

        recordedStandardDowntimeMinutes:
            round(
                standardActualMinutes
            ),

        standardPlannedDowntimeMinutes:
            round(
                standardApplied
            ),

        remainingStandardAllowanceMinutes:
            round(
                remainingStandardAllowance
            ),

        standardExcessDowntimeMinutes:
            round(
                standardExcess
            ),


        // ----------------------------------------
        // ADDITIONAL PLANNED
        // ----------------------------------------

        additionalPlannedDowntimeMinutes:
            round(
                additionalPlannedMinutes
            ),

        appliedPlannedDowntime:
            round(
                plannedDowntimeMinutes
            ),


        // ----------------------------------------
        // STOP INFORMATION
        // ----------------------------------------

        completedStops:
            completedStops,

        totalStops:
            rows.length,

        openStop:
            openStop,

        currentOpenStopMinutes:
            round(
                currentOpenStopMinutes
            ),

        maximumDowntimeMinutes:
            round(
                maximumDowntimeMinutes
            ),


        // ----------------------------------------
        // LINE CONFIGURATION
        // ----------------------------------------

        ratedLineSpeed:
            lineSpeed,

        tileSize:
            tileSize,

        stopDelayMs:
            Number(
                ls.stopDelayMs ??
                cfg.stopDelayMs ??
                60000
            ),

        maxPulseGapMs:
            Number(
                ls.maxPulseGapMs ??
                cfg.maxPulseGapMs ??
                10000
            ),

        requiredRunTimeMs:
            Number(
                ls.requiredRunTimeMs ??
                cfg.requiredRunTimeMs ??
                60000
            ),


        // Availability may legitimately exceed
        // 100% under this planned-downtime model.
        availabilityMayExceed100:
            true,


        source:
            "shift-summary",

        updatedAt:
            new Date().toISOString()
    }
};


// ========================================================
// SAVE TO MONGODB
// ========================================================

msg.collection =
    "shifts";

msg.operation =
    "insertOne";


return msg;

const req = msg.summaryRequest;

if (
    !req ||
    !req.device ||
    !req.shift ||
    !req.shiftDate ||
    !req.fromTime ||
    !req.toTime
) {
    node.warn(
        "Code-wise enrichment skipped: summaryRequest is missing"
    );
    return null;
}

function esc(v) {
    return String(v ?? "")
        .replace(/\\/g, "\\\\")
        .replace(/"/g, '\\"');
}

msg.codeWiseTarget = {
    device: req.device,
    line: req.line,
    shift: req.shift,
    shiftDate: req.shiftDate,
    fromTime: req.fromTime,
    toTime: req.toTime,
    productionRunIdAtShiftEnd: req.productionRunIdAtShiftEnd || null,
    productionRunStartTimeAtShiftEnd: req.productionRunStartTimeAtShiftEnd || null
};

const device = esc(req.device);
const shift = esc(req.shift);
const shiftDate = esc(req.shiftDate);
const fromTime = esc(req.fromTime);
const toTime = esc(req.toTime);

// Read the completed shift's cumulative shift_count records.
// Difference calculation and design-code grouping are performed
// in the next Node-RED function for better Flux compatibility.
msg.query = `
from(bucket: "RCLH")
  |> range(
      start: time(v: "${fromTime}"),
      stop: time(v: "${toTime}")
  )
  |> filter(fn: (r) =>
      r["_measurement"] == "tile_events" and
      r["_field"] == "shift_count" and
      r["device"] == "${device}" and
      r["shift"] == "${shift}" and
      r["shiftDate"] == "${shiftDate}"
  )
  |> group(columns: ["device", "shift", "shiftDate"])
  |> sort(columns: ["_time"])
  |> keep(
      columns: [
          "_time",
          "_value",
          "designCode",
          "tileSize",
          "productionRunId",
          "productionRunStartTime"
      ]
  )
`;

node.warn(
    `Code-wise shift_count query: ${req.device} | ` +
    `${req.shiftDate} | ${req.shift} | ` +
    `${req.fromTime} -> ${req.toTime}`
);

return msg;

const rows = (Array.isArray(msg.payload) ? msg.payload : [])
    .filter(row => Number.isFinite(Number(row?._value)))
    .sort((a, b) => {
        const ta = new Date(a?._time || 0).getTime();
        const tb = new Date(b?._time || 0).getTime();
        return ta - tb;
    });

const target = msg.codeWiseTarget;

if (!target) {
    node.error("Code-wise target identity was lost", msg);
    return null;
}

function round(v, n = 2) {
    const p = 10 ** n;
    return Math.round((Number(v || 0) + Number.EPSILON) * p) / p;
}

function tileAreaM2(size) {
    const d = String(size || "")
        .toLowerCase()
        .replace(/\s+/g, "")
        .split("x")
        .map(Number);

    if (
        d.length !== 2 ||
        !d.every(v => Number.isFinite(v) && v > 0)
    ) {
        return 0;
    }

    return (d[0] * d[1]) / 10000;
}

function cleanText(value, fallback) {
    const text = String(value ?? "").trim();
    return text || fallback;
}

function isoTime(value) {
    if (value === undefined || value === null || value === "") return null;
    const ms = new Date(value).getTime();
    return Number.isFinite(ms) ? new Date(ms).toISOString() : null;
}

const aggregateMap = new Map();
const timeline = [];

let previousShiftCount = 0;
let ignoredRollbacks = 0;
let activeRun = null;

for (const row of rows) {
    const currentShiftCount = Number(row._value);
    const delta = currentShiftCount - previousShiftCount;

    // Keep the last valid cumulative value if a lower/stale value
    // appears. This prevents the next valid row creating a spike.
    if (!Number.isFinite(delta) || delta < 0) {
        ignoredRollbacks += 1;

        node.warn(
            "Completed-shift shift_count rollback ignored: " +
            "previous=" + previousShiftCount +
            ", current=" + currentShiftCount +
            ", time=" + String(row?._time || "")
        );

        continue;
    }

    previousShiftCount = currentShiftCount;

    if (delta === 0) {
        continue;
    }

    const designCode = cleanText(row.designCode, "Unknown");
    const tileSize = cleanText(row.tileSize, "Unknown");
    const producedAt = isoTime(row._time);
    const production = delta * tileAreaM2(tileSize);

    // Prefer immutable tags written alongside each counter event.
    // Without these tags, a global setting read at shift end cannot
    // determine which earlier run produced a tile before a changeover.
    let productionRunId = cleanText(row.productionRunId, "") || null;
    let productionRunStartTime = isoTime(row.productionRunStartTime);
    let runIdSource = productionRunId ? "influx-event" : "unresolved";

    // Conservative fallback for legacy telemetry: only associate a row
    // with the end-of-shift run if the event is on/after its start AND
    // its tile size agrees. Do not guess the earlier production run.
    const fallbackStart = isoTime(target.productionRunStartTimeAtShiftEnd);
    const fallbackId = target.productionRunIdAtShiftEnd || null;
    if (!productionRunId && fallbackId && fallbackStart &&
        producedAt && Date.parse(producedAt) >= Date.parse(fallbackStart)) {
        const settings = global.get("lineSettings") || {};
        const ls = settings[target.line] || settings[String(target.line || "").toLowerCase()] || {};
        if (String(ls.tileSize || "").trim() === tileSize &&
            String(ls.productionRunId || "") === String(fallbackId)) {
            productionRunId = String(fallbackId);
            productionRunStartTime = fallbackStart;
            runIdSource = "shift-end-fallback";
        }
    }

    const key = JSON.stringify([designCode, tileSize, productionRunId, productionRunStartTime]);

    // ----------------------------------------------------------
    // AGGREGATED TOTAL PER DESIGN CODE + TILE SIZE
    // sequence records when this design was first produced.
    // ----------------------------------------------------------
    const aggregate = aggregateMap.get(key) || {
        sequence: aggregateMap.size + 1,
        designCode,
        tileSize,
        productionRunId,
        productionRunStartTime,
        runIdSource,
        firstProducedAt: producedAt,
        lastProducedAt: producedAt,
        tileCount: 0,
        production: 0
    };

    if (!aggregate.firstProducedAt && producedAt) {
        aggregate.firstProducedAt = producedAt;
    }

    if (producedAt) {
        aggregate.lastProducedAt = producedAt;
    }

    aggregate.tileCount += delta;
    aggregate.production += production;
    aggregateMap.set(key, aggregate);

    // ----------------------------------------------------------
    // CHRONOLOGICAL PRODUCTION RUNS
    // A -> B -> A is saved as three separate timeline entries.
    // ----------------------------------------------------------
    if (!activeRun || activeRun.key !== key) {
        activeRun = {
            key,
            sequence: timeline.length + 1,
            designCode,
            tileSize,
            productionRunId,
            productionRunStartTime,
            runIdSource,
            startTime: producedAt,
            endTime: producedAt,
            tileCount: 0,
            production: 0
        };

        timeline.push(activeRun);
    }

    if (!activeRun.startTime && producedAt) {
        activeRun.startTime = producedAt;
    }

    if (producedAt) {
        activeRun.endTime = producedAt;
    }

    activeRun.tileCount += delta;
    activeRun.production += production;
}

// Unique design-code totals, ordered by first production time.
msg.codeWiseProduction = [...aggregateMap.values()]
    .map(item => ({
        sequence: item.sequence,
        designCode: item.designCode,
        tileSize: item.tileSize,
        productionRunId: item.productionRunId,
        productionRunStartTime: item.productionRunStartTime,
        runIdSource: item.runIdSource,
        firstProducedAt: item.firstProducedAt,
        lastProducedAt: item.lastProducedAt,
        tileCount: Math.round(item.tileCount),
        production: round(item.production)
    }))
    .sort((a, b) => a.sequence - b.sequence);

// Every chronological production run. Use this array for a chart
// where the left side is the first run and the right side is the last.
msg.codeWiseProductionTimeline = timeline
    .map(({key, ...item}) => ({
        ...item,
        tileCount: Math.round(item.tileCount),
        production: round(item.production)
    }))
    .sort((a, b) => a.sequence - b.sequence);

const calculatedTileCount = msg.codeWiseProduction.reduce(
    (sum, item) => sum + Number(item.tileCount || 0),
    0
);

node.status({
    fill: ignoredRollbacks > 0 ? "yellow" : "green",
    shape: ignoredRollbacks > 0 ? "ring" : "dot",
    text:
        rows.length + " rows -> " +
        msg.codeWiseProduction.length + " codes, " +
        msg.codeWiseProductionTimeline.length + " runs, " +
        calculatedTileCount + " tiles"
});

return msg;

// const target = msg.codeWiseTarget;

// if (!target || !target.device || !target.shift || !target.shiftDate) {
//     node.error("Cannot update shift: codeWiseTarget is invalid", msg);
//     return null;
// }

// msg.collection = "shifts";
// msg.mode = "collection";
// msg.operation = "updateOne";

// msg.payload = [
//     {
//         "lineStats.device": target.device,
//         "lineStats.shift": target.shift,
//         "lineStats.shiftDate": target.shiftDate
//     },
//     {
//         $set: {
//             // Aggregated unique design totals in first-produced order.
//             "lineStats.codeWiseProduction":
//                 Array.isArray(msg.codeWiseProduction)
//                     ? msg.codeWiseProduction
//                     : [],

//             // Complete run order. This preserves A -> B -> A.
//             "lineStats.codeWiseProductionTimeline":
//                 Array.isArray(msg.codeWiseProductionTimeline)
//                     ? msg.codeWiseProductionTimeline
//                     : [],

//             "lineStats.codeWiseUpdatedAt": new Date().toISOString()
//         }
//     }
// ];

// return msg;

const target = msg.codeWiseTarget;

if (!target || !target.device || !target.shift || !target.shiftDate) {
    node.error("Cannot update shift: codeWiseTarget is invalid", msg);
    return null;
}

const codeWise = Array.isArray(msg.codeWiseProduction)
    ? msg.codeWiseProduction
    : [];

const timeline = Array.isArray(msg.codeWiseProductionTimeline)
    ? msg.codeWiseProductionTimeline
    : [];

function round(value, decimals = 2) {
    const p = 10 ** decimals;
    return Math.round((value + Number.EPSILON) * p) / p;
}

function normalizeSize(value) {
    return String(value ?? "")
        .trim()
        .toLowerCase()
        .replace(/\s+/g, "")
        .replace(/×/g, "x");
}

function tileAreaM2(size) {
    const dimensions = size.split("x").map(Number);

    if (
        dimensions.length !== 2 ||
        !dimensions.every(n => Number.isFinite(n) && n > 0)
    ) {
        return null;
    }

    // Dimensions are in centimetres.
    return dimensions[0] * dimensions[1] / 10000;
}

const sizes = new Map();

for (const row of codeWise) {
    const tileSize = normalizeSize(row.tileSize);
    const tileCount = Number(row.tileCount);
    const area = tileAreaM2(tileSize);

